from collections import deque
def tree(values):
    """Build a tree from values listed level by level, None for a missing child: [5, 1, 6, None, None, 3, 7]."""
    if not values or values[0] is None:
        return None
    root = TreeNode(values[0])
    queue = deque([root])
    position = 1
    while queue and position < len(values):
        node = queue.popleft()
        for side in ("left", "right"):
            if position < len(values) and values[position] is not None:
                child = TreeNode(values[position])
                setattr(node, side, child)
                queue.append(child)
            position += 1
    return root
def balanced(low, high):
    """A valid search tree holding every integer from low to high, as balanced as it can be."""
    if low > high:
        return None
    middle = (low + high) // 2
    return TreeNode(middle, balanced(low, middle - 1), balanced(middle + 1, high))
